const body = $input.first().json.body;
const github = body.workflow_run;
const gitlab = body.object_attributes;
const alert = github
  ? { platform: 'GitHub', project: body.repository.full_name, branch: github.head_branch, status: github.conclusion, url: github.html_url }
  : { platform: 'GitLab', project: body.project.path_with_namespace, branch: gitlab.ref, status: gitlab.status, url: gitlab.url };
alert.message = `${alert.platform}: ${alert.project} (${alert.branch}) is ${alert.status}`;
return [{ json: alert }];
